// SAMPLE RTL for UI development
// v1, attempt 1: 4-lane 8-bit MAC, 16 cycles, 16-bit accumulator.
module mac4 (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        start,
  input  wire [31:0] a,          // four 8-bit lanes
  input  wire [31:0] b,          // four 8-bit lanes
  output reg  [15:0] acc,
  output reg         done
);
  reg [4:0] cycle;
  reg       busy;
  wire [15:0] p0 = a[7:0]   * b[7:0];
  wire [15:0] p1 = a[15:8]  * b[15:8];
  wire [15:0] p2 = a[23:16] * b[23:16];
  wire [15:0] p3 = a[31:24] * b[31:24];
  wire [15:0] sum = p0 + p1 + p2 + p3;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      acc   <= 16'd0;
      cycle <= 5'd0;
      busy  <= 1'b0;
      done  <= 1'b0;
    end else if (start && !busy) begin
      acc   <= 16'd0;
      cycle <= 5'd0;
      busy  <= 1'b1;
      done  <= 1'b0;
    end else if (busy) begin
      acc   <= acc + sum;
      cycle <= cycle + 5'd1;
      if (cycle == 5'd15) begin
        busy <= 1'b0;
        done <= 1'b1;
      end
    end
  end
endmodule

